public sealed class RecordingLedger : ILedger
{
    private readonly List<Operation> _journal = new();
    public decimal Balance { get; private set; }

    public void Deposit(decimal amount)
    {
        Balance += amount;                              // working behaviour
        _journal.Add(new Operation("deposit", amount)); // recorded interaction
    }

    public IReadOnlyList<Operation> Journal => _journal; // test-only accessor
}
